    for (const m of body.matchAll(/@([A-Za-z0-9_.-]+)/g)) {
      const u = db.users.find(x => x.username.toLowerCase() === m[1].toLowerCase().replace(/[.-]+$/, '') || x.username.toLowerCase() === m[1].toLowerCase());
